function sectionsFor(question){const q=question.toLowerCase(),sections=[];if(/route|rute|rutten|rutt|маршрут|дорог|шлях|вей/.test(q))sections.push('scenicRoutes');if(/sauna|badstue|bastu|саун|бан[яі]|hytte|cabin|будиноч|домик|котедж/.test(q))sections.push('staysSauna');if(/caf[eé]|kaf[eé]|кав.?яр|кофе|кафе|kafé/.test(q))sections.push('cafeNearby');if(/attrac|experience|park|розваг|атрак|famil|сімейн/.test(q))sections.push('routeExperiences');if(/story|histor|істор|истор/.test(q))sections.push('travelStories');if(!sections.includes('scenicRoutes')&&/waterfall|foss|водопад|водоспад|fjord|фьорд|фіорд|photo|фото|місц|мест/.test(q))sections.push('collection');return sections}
function navigationFor(data,question){const candidates=Array.isArray(data.navigation)?data.navigation.map(item=>typeof item==='string'?item:item?.section):sectionsFor(question);return [...new Set(candidates)].filter(section=>navigationSections.includes(section)&&document.getElementById(section))}
